func supersessionFixture(t *testing.T) (CatalogSupersessionState, CatalogSupersessionCapability, CatalogSupersessionCommand, CatalogSupersessionContext) {
	t.Helper()
	op := SourceRegistration{binding: &sourceBinding{id: SourceID{value: registrationOpaque(5)}, revision: RegistrationRevision{value: registrationOpaque(6)}, issuer: IssuerPrincipal{value: registrationOpaque(7)}, adapter: "op", adapterVersion: "1", scope: "catalog", acquisition: CoreOperator, claims: 1 << OwnershipClaimKey}}
	review, _ := NewReviewCapability(IssuerPrincipal{value: registrationOpaque(8)}, op)
	cap, err := NewCatalogSupersessionCapability(review)
	if err != nil {
		t.Fatal(err)
	}
	content, _ := identity.ParseContentID(registrationID("cnt_", 1))
	oldID, _ := identity.ParseContentVersionID(registrationID("ver_", 2))
	newID, _ := identity.ParseContentVersionID(registrationID("ver_", 3))
	old, _ := NewContentVersion(oldID, content, mustFingerprint(t, mustAudioID(t, 1), mustAudioHash(t, strings.Repeat("11", 20))), UnknownVersionOrderEvidence())
	next, _ := NewContentVersion(newID, content, mustFingerprint(t, mustAudioID(t, 2), mustAudioHash(t, strings.Repeat("22", 20))), UnknownVersionOrderEvidence())
	state, err := NewCatalogSupersessionState(content, []ContentVersion{next, old})
	if err != nil {
		t.Fatal(err)
	}
	command := CatalogSupersessionCommand{ID: CatalogCommandID{value: registrationOpaque(4)}, Content: content, Old: old, New: next, Source: op, ExpectedAggregate: CatalogRevision{3}, ExpectedSupersession: CatalogRevision{1}, ExpectedOldReview: CatalogRevision{1}, ExpectedNewReview: CatalogRevision{1}, Reason: "correct"}
	command.Evidence = []CatalogSupersessionEvidence{supersessionEvidence(t, command, 9, 10)}
	command.Support = []evidence.ID{command.Evidence[0].ID()}
	context := CatalogSupersessionContext{AggregateRevision: CatalogRevision{3}, OldReview: supersessionReview(t, old, false), NewReview: supersessionReview(t, next, true), OrderRevision: CatalogRevision{3}}
	return state, cap, command, context
}

func supersessionEvidence(t *testing.T, c CatalogSupersessionCommand, id, batch byte) CatalogSupersessionEvidence {
	t.Helper()
	ingest := IngestCapability{binding: c.Source.binding}
	a, err := NewArtifact(ingest, c.Source, ArtifactFacts{ID: BatchID{value: registrationOpaque(batch)}, SHA256: sha256.Sum256([]byte("{}")), ByteLength: 2, RecordCount: 1, ParserRevision: "1"})
	if err != nil {
		t.Fatal(err)
	}
	snapshot, _ := NewRecordSnapshot([]byte("{}"))
	coordinate, _ := NewRecordCoordinate(a, 0, "0", snapshot)
	alphabet := "0123456789abcdefghjkmnpqrstvwxyz"
	eid, _ := evidence.ParseID("obs_" + strings.Repeat("0", 24) + string(alphabet[id/32]) + string(alphabet[id%32]))
	e, err := NewCatalogSupersessionEvidence(ingest, c.Source, CatalogSupersessionEvidenceInput{ID: eid, Content: c.Content, OldVersion: c.Old.id, NewVersion: c.New.id, Coordinate: coordinate, ObservedAt: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)})
	if err != nil {
		t.Fatal(err)
	}
	return e
}

// Build an actual F01 bootstrap so revision-1 accepted fields in the normative
// fixture have authoring evidence rather than a manually edited projection.
func supersessionReview(t *testing.T, v ContentVersion, accepted bool) CatalogReviewState {
	t.Helper()
	subject, _ := VersionSubject(v.contentID, v.id)
	if !accepted {
		s, _ := NewCatalogReviewState(subject, false)
		return s
	}
	cap, command := registrationFixture(t, RegisterCatalogVersion)
	command.Subject = subject
	fingerprint, _ := FingerprintClaim(v.fingerprint)
	owner, _ := OwnershipClaim(v.contentID)
	command.Observations = []CatalogObservation{registrationObservation(t, SourceRegistration{binding: cap.evidence[1].binding}, subject, fingerprint, 14, 15), registrationObservation(t, command.Source, subject, owner, 16, 17)}
	command.Selections = []CatalogRegistrationSelection{{Key: FingerprintClaimKey, Observation: command.Observations[0].ID()}, {Key: OwnershipClaimKey, Observation: command.Observations[1].ID()}}
	s, _, err := NewRegisteredCatalogReviewState(cap, command, CatalogRegistrationContext{OrderRevision: CatalogRevision{2}})
	if err != nil {
		t.Fatal(err)
	}
	return s
}

func supersessionApply(t *testing.T, s CatalogSupersessionState, cap CatalogSupersessionCapability, c CatalogSupersessionCommand, ctx CatalogSupersessionContext) (CatalogSupersessionState, CatalogSupersessionResult) {
	t.Helper()
	next, r, err := s.Apply(cap, c, ctx)
	if err != nil {
		t.Fatal(err)
	}
	return next, r
}
func supersessionReject(t *testing.T, s CatalogSupersessionState, cap CatalogSupersessionCapability, c CatalogSupersessionCommand, ctx CatalogSupersessionContext, want error) {
	t.Helper()
	before, _ := s.PersistenceEncoding()
	next, r, err := s.Apply(cap, c, ctx)
	var limit LimitError
	if want == nil {
		if !errors.As(err, &limit) {
			t.Fatalf("want limit, got %v", err)
		}
	} else if !errors.Is(err, want) {
		t.Fatalf("want %v, got %v", want, err)
	}
	after, _ := next.PersistenceEncoding()
	if !bytes.Equal(before, after) || !reflect.DeepEqual(s, next) || r.Command != (CatalogCommandID{}) {
		t.Fatal("rejection mutated state or returned result")
	}
}

func TestSupersessionTransitions(t *testing.T) {
	s, cap, c, ctx := supersessionFixture(t)
	next, r := supersessionApply(t, s, cap, c, ctx)
	if s.Revision().value != 1 || next.Revision().value != 2 || r.AggregateRevision.value != 4 || r.OldReviewRevision != ctx.OldReview.revision || r.OrderRevision != ctx.OrderRevision {
		t.Fatal("incorrect state/revision")
	}
	thirdID, _ := identity.ParseContentVersionID(registrationID("ver_", 18))
	third, _ := NewContentVersion(thirdID, c.Content, c.New.fingerprint, UnknownVersionOrderEvidence())
	fourthID, _ := identity.ParseContentVersionID(registrationID("ver_", 19))
	fourth, _ := NewContentVersion(fourthID, c.Content, c.New.fingerprint, UnknownVersionOrderEvidence())
	grown, err := next.WithVersions(append(next.Versions(), third, fourth))
	if err != nil {
		t.Fatal(err)
	}
	c2 := c
	c2.ID = CatalogCommandID{value: registrationOpaque(20)}
	c2.Old = c.New
	c2.New = third
	c2.ExpectedAggregate = CatalogRevision{7}
	c2.ExpectedSupersession = CatalogRevision{2}
	c2.Evidence = []CatalogSupersessionEvidence{supersessionEvidence(t, c2, 21, 22)}
	c2.Support = []evidence.ID{c2.Evidence[0].ID()}
	ctx2 := ctx
	ctx2.AggregateRevision = c2.ExpectedAggregate
	ctx2.OldReview = supersessionReview(t, c2.Old, true)
	ctx2.NewReview = supersessionReview(t, c2.New, true)
	ctx2.ProtectedCustom = true
	chain, _ := supersessionApply(t, grown, cap, c2, ctx2)
	for _, tc := range []struct {
		name     string
		old, new ContentVersion
	}{{"branch", c.Old, fourth}, {"cycle", third, c.Old}, {"merge", fourth, c.New}, {"shortcut", c.Old, third}, {"target-in-chain", fourth, third}} {
		t.Run(tc.name, func(t *testing.T) {
			bad := c2
			bad.ID = CatalogCommandID{value: registrationOpaque(23)}
			bad.Old = tc.old
			bad.New = tc.new
			bad.ExpectedAggregate = CatalogRevision{8}
			bad.ExpectedSupersession = CatalogRevision{3}
			bad.Evidence = []CatalogSupersessionEvidence{supersessionEvidence(t, bad, 24, 25)}
			bad.Support = []evidence.ID{bad.Evidence[0].ID()}
			context := ctx2
			context.AggregateRevision = bad.ExpectedAggregate
			context.OldReview = supersessionReview(t, bad.Old, false)
			context.NewReview = supersessionReview(t, bad.New, true)
			supersessionReject(t, chain, cap, bad, context, ErrCatalogCommandConflict)
		})
	}
	bad := c
	bad.New = bad.Old
	supersessionReject(t, s, cap, bad, ctx, ErrInvalidCatalog)
	bad = c
	foreign, _ := identity.ParseContentID(registrationID("cnt_", 26))
	bad.New.contentID = foreign
	supersessionReject(t, s, cap, bad, ctx, ErrCatalogSubjectMismatch)
	bad = c
	bad.Old.fingerprint = bad.New.fingerprint
	supersessionReject(t, s, cap, bad, ctx, ErrVersionIdentityConflict)
	bad = c
	bad.ExpectedAggregate = CatalogRevision{2}
	supersessionReject(t, s, cap, bad, ctx, ErrCatalogRevisionConflict)
	bad = c
	bad.ExpectedSupersession = CatalogRevision{2}
	supersessionReject(t, s, cap, bad, ctx, ErrCatalogRevisionConflict)
	bad = c
	bad.ExpectedOldReview = CatalogRevision{2}
	supersessionReject(t, s, cap, bad, ctx, ErrCatalogRevisionConflict)
	bad = c
	bad.ExpectedNewReview = CatalogRevision{2}
	supersessionReject(t, s, cap, bad, ctx, ErrCatalogRevisionConflict)
	unsupported := ctx
	unsupported.NewReview = supersessionReview(t, c.New, false)
	supersessionReject(t, s, cap, c, unsupported, ErrCatalogUnsupported)
	if _, err := grown.WithVersions([]ContentVersion{c.New, third}); !errors.Is(err, ErrVersionIdentityConflict) {
		t.Fatal("removed immutable manifest member")
	}
	badState := next
	badState.edges = badState.History()
	badState.edges[0].Result.Old = third
	supersessionReject(t, badState, cap, c, ctx, ErrInvalidCatalog)
	// Exact old result survives later edges, higher aggregate/order revisions and
	// a changed endpoint review projection, without retargeting Old/New.
	_, replay := supersessionApply(t, chain, cap, c, CatalogSupersessionContext{})
	if !reflect.DeepEqual(r, replay) {
		t.Fatal("replay used current projection")
	}
}

func TestSupersessionAuthority(t *testing.T) {
	s, cap, c, ctx := supersessionFixture(t)
	if _, err := NewCatalogSupersessionCapability(ReviewCapability{}); !errors.Is(err, ErrCatalogUnauthorized) {
		t.Fatal(err)
	}
	for _, kind := range []AcquisitionClass{OfflinePublic, OfflineCustom, BaselineSnapshot, LocalVerification} {
		t.Run(fmt.Sprint(kind), func(t *testing.T) {
			source := SourceRegistration{binding: &sourceBinding{id: SourceID{value: registrationOpaque(5)}, acquisition: kind, claims: 1 << OwnershipClaimKey}}
			review, _ := NewReviewCapability(cap.Reviewer(), source)
			if _, err := NewCatalogSupersessionCapability(review); !errors.Is(err, ErrCatalogUnauthorized) {
				t.Fatal(err)
			}
		})
	}
	noOwnership := SourceRegistration{binding: &sourceBinding{acquisition: CoreOperator, claims: 1 << TitleClaimKey}}
	review, _ := NewReviewCapability(cap.Reviewer(), noOwnership)
	if _, err := NewCatalogSupersessionCapability(review); !errors.Is(err, ErrCatalogUnauthorized) {
		t.Fatal(err)
	}
	supersessionReject(t, s, CatalogSupersessionCapability{}, c, ctx, ErrCatalogUnauthorized)
	_, otherCap, _, _ := supersessionFixture(t)
	supersessionReject(t, s, otherCap, c, ctx, ErrCatalogSourceMismatch)
	next, _ := supersessionApply(t, s, cap, c, ctx)
	cap.Source().Revoke()
	supersessionReject(t, next, cap, c, ctx, ErrCatalogUnauthorized)
	raw, err := next.PersistenceEncoding()
	if err != nil {
		t.Fatal(err)
	}
	detached, err := RehydrateCatalogSupersessionState(raw, CatalogPersistenceBindings{AllowUnbound: true})
	if err != nil {
		t.Fatal(err)
	}
	if detached.History()[0].Command.Source.Active() {
		t.Fatal("decoded source authorized")
	}
	if _, err := NewCatalogSupersessionCapability(ReviewCapability{binding: detached.edges[0].Command.Source.binding, reviewer: cap.Reviewer()}); !errors.Is(err, ErrCatalogUnauthorized) {
		t.Fatal(err)
	}
	_, restoredCap, _, _ := supersessionFixture(t)
	bindings := CatalogPersistenceBindings{Sources: []SourceRegistration{restoredCap.Source()}, Reviewers: []IssuerPrincipal{restoredCap.Reviewer()}}
	rebound, err := RehydrateCatalogSupersessionState(raw, bindings)
	if err != nil {
		t.Fatal(err)
	}
	replayCommand := rebound.History()[0].Command
	supersessionApply(t, rebound, restoredCap, replayCommand, CatalogSupersessionContext{})
	for _, field := range []string{"id", "revision", "issuer", "adapter", "adapterVersion", "scope", "claims", "acquisition"} {
		t.Run("binding-"+field, func(t *testing.T) {
			_, fresh, _, _ := supersessionFixture(t)
			b := fresh.Source().binding
			switch field {
			case "id":
				b.id.value[0] = 1
			case "revision":
				b.revision.value[0] = 1
			case "issuer":
				b.issuer.value[0] = 1
			case "adapter":
				b.adapter = "changed"
			case "adapterVersion":
				b.adapterVersion = "2"
			case "scope":
				b.scope = "changed"
			case "claims":
				b.claims |= 1 << TitleClaimKey
			case "acquisition":
				b.acquisition = BaselineSnapshot
			}
			if _, err := RehydrateCatalogSupersessionState(raw, CatalogPersistenceBindings{Sources: []SourceRegistration{fresh.Source()}, Reviewers: []IssuerPrincipal{fresh.Reviewer()}}); err == nil {
				t.Fatal("changed complete binding accepted")
			}
		})
	}
	if _, err := RehydrateCatalogSupersessionState(raw, CatalogPersistenceBindings{Sources: bindings.Sources}); !errors.Is(err, ErrCatalogUnauthorized) {
		t.Fatal("missing reviewer accepted", err)
	}
}

func TestSupersessionReplayEvidence(t *testing.T) {
	s, cap, c, ctx := supersessionFixture(t)
	next, result := supersessionApply(t, s, cap, c, ctx)
	for _, field := range []string{"reason", "expected", "reviewer", "tuple", "source", "evidence", "support"} {
		t.Run(field, func(t *testing.T) {
			bad := cloneSupersessionCommand(c)
			grant := cap
			want := ErrCatalogCommandConflict
			switch field {
			case "reason":
				bad.Reason = "changed"
			case "expected":
				bad.ExpectedAggregate = CatalogRevision{8}
			case "reviewer":
				grant.review.reviewer.value[0] = 1
			case "tuple":
				bad.Old.order, _ = NewVersionOrderEvidence("legacy", 7)
			case "source":
				bad.Source = SourceRegistration{}
				want = ErrCatalogUnauthorized
			case "evidence":
				bad.Evidence[0].input.AssertedOrigin = "changed"
			case "support":
				bad.Support = nil
				want = ErrCatalogUnsupported
			}
			supersessionReject(t, next, grant, bad, ctx, want)
		})
	}
	for _, kind := range []string{"duplicate-evidence", "duplicate-support", "missing-support", "extra-support", "wrong-pair", "wrong-source", "own-batch-key", "changed-record"} {
		t.Run(kind, func(t *testing.T) {
			bad := cloneSupersessionCommand(c)
			want := ErrInvalidCatalog
			switch kind {
			case "duplicate-evidence":
				bad.Evidence = append(bad.Evidence, bad.Evidence[0])
				bad.Support = append(bad.Support, bad.Support[0])
			case "duplicate-support":
				bad.Evidence = append(bad.Evidence, supersessionEvidence(t, c, 11, 12))
				bad.Support = append(bad.Support, bad.Support[0])
			case "missing-support":
				bad.Support = nil
				want = ErrCatalogUnsupported
			case "extra-support":
				bad.Support = append(bad.Support, evidence.ID{})
				want = ErrCatalogUnsupported
			case "wrong-pair":
				bad.Evidence[0].input.NewVersion = bad.Old.id
				want = ErrCatalogSubjectMismatch
			case "wrong-source":
				_, other, _, _ := supersessionFixture(t)
				bad.Evidence[0].input.Coordinate.artifact.source = other.Source()
				want = ErrCatalogSourceMismatch
			case "own-batch-key":
				bad.Evidence[0].input.Coordinate.artifact.facts.ID.value = c.ID.value
				want = ErrCatalogCommandConflict
			case "changed-record":
				second := supersessionEvidence(t, c, 11, 10)
				second.input.Coordinate.locator = "changed"
				bad.Evidence = append(bad.Evidence, second)
				bad.Support = append(bad.Support, second.ID())
				want = ErrCatalogObservationConflict
			}
			supersessionReject(t, s, cap, bad, ctx, want)
		})
	}
	// Every exposed slice is a copy, including nested historical slices.
	before, _ := next.PersistenceEncoding()
	history := next.History()
	history[0].Command.Support[0] = evidence.ID{}
	history[0].Result.Support[0] = evidence.ID{}
	history[0].Command.Evidence[0] = CatalogSupersessionEvidence{}
	versions := next.Versions()
	versions[0] = ContentVersion{}
	result.Support[0] = evidence.ID{}
	c.Support[0] = evidence.ID{}
	after, _ := next.PersistenceEncoding()
	if !bytes.Equal(before, after) {
		t.Fatal("caller mutated retained history")
	}
}

func TestSupersessionBounds(t *testing.T) {
	s, cap, c, ctx := supersessionFixture(t)
	for _, length := range []int{4096, 4097} {
		t.Run(fmt.Sprint(length), func(t *testing.T) {
			bad := c
			bad.Reason = strings.Repeat("x", length)
			if length == 4096 {
				supersessionApply(t, s, cap, bad, ctx)
			} else {
				supersessionReject(t, s, cap, bad, ctx, nil)
			}
		})
	}
	for _, reason := range []string{"", "x\x00", "\xff"} {
		bad := c
		bad.Reason = reason
		supersessionReject(t, s, cap, bad, ctx, ErrInvalidCatalog)
	}
	for _, count := range []int{64, 65} {
		t.Run(fmt.Sprintf("evidence-%d", count), func(t *testing.T) {
			bad := c
			bad.Evidence = nil
			bad.Support = nil
			for i := 0; i < count; i++ {
				e := supersessionEvidence(t, c, byte(i+32), byte(i+128))
				bad.Evidence = append(bad.Evidence, e)
				bad.Support = append(bad.Support, e.ID())
			}
			if count == 64 {
				supersessionApply(t, s, cap, bad, ctx)
			} else {
				supersessionReject(t, s, cap, bad, ctx, nil)
			}
		})
	}
	bad := c
	bad.ExpectedAggregate = CatalogRevision{math.MaxInt64}
	overflow := ctx
	overflow.AggregateRevision = bad.ExpectedAggregate
	supersessionReject(t, s, cap, bad, overflow, ErrCatalogRevisionOverflow)
	bad = c
	bad.ExpectedAggregate = CatalogRevision{}
	supersessionReject(t, s, cap, bad, ctx, ErrInvalidCatalog)
	versions := make([]ContentVersion, 1024)
	for i := range versions {
		id, _ := identity.ParseContentVersionID(fmt.Sprintf("ver_%026x", i+1))
		versions[i], _ = NewContentVersion(id, c.Content, c.New.fingerprint, UnknownVersionOrderEvidence())
	}
	if _, err := NewCatalogSupersessionState(c.Content, versions); err != nil {
		t.Fatal(err)
	}
	if _, err := NewCatalogSupersessionState(c.Content, append(versions, c.New)); err == nil {
		t.Fatal("1025 versions accepted")
	}
	next, _ := supersessionApply(t, s, cap, c, ctx)
	raw, _ := next.PersistenceEncoding()
	if size, err := next.RetainedEncodingSize(); err != nil || size != uint64(len(raw)) {
		t.Fatal("encoded-byte accounting", err)
	}
	oversized := make([]byte, RetainedBytes.Maximum()+1)
	if _, err := RehydrateCatalogSupersessionState(oversized, CatalogPersistenceBindings{AllowUnbound: true}); err == nil {
		t.Fatal("oversized state")
	}
	var encoder catalogEncoder
	encoder.size = RetainedBytes.Maximum() - 1
	encoder.raw("x")
	if encoder.err != nil {
		t.Fatal(encoder.err)
	}
	encoder.raw("x")
	if encoder.err == nil {
		t.Fatal("one-over encoding")
	}
	// An advertised count/length cannot allocate before enough bytes exist.
	for _, offset := range []int{len("pi08-version-supersession-state/1") + 8 + 38 + 8} {
		malformed := append([]byte(nil), raw...)
		binary.BigEndian.PutUint64(malformed[offset:offset+8], math.MaxUint64)
		if _, err := RehydrateCatalogSupersessionState(malformed, CatalogPersistenceBindings{AllowUnbound: true}); err == nil {
			t.Fatal("unchecked count")
		}
	}
}

func TestSupersessionDecoding(t *testing.T) {
	s, cap, c, ctx := supersessionFixture(t)
	next, r := supersessionApply(t, s, cap, c, ctx)
	bindings := CatalogPersistenceBindings{Sources: []SourceRegistration{cap.Source()}, Reviewers: []IssuerPrincipal{cap.Reviewer()}}
	command, _ := c.CanonicalEncoding(cap)
	result, _ := r.CanonicalEncoding()
	state, _ := next.PersistenceEncoding()
	for name, raw := range map[string][]byte{"command": command, "result": result, "state": state} {
		t.Run(name, func(t *testing.T) {
			decode := func(b []byte) error {
				switch name {
				case "command":
					_, _, err := RehydrateCatalogSupersessionCommand(b, bindings)
					return err
				case "result":
					_, err := RehydrateCatalogSupersessionResult(b)
					return err
				default:
					_, err := RehydrateCatalogSupersessionState(b, bindings)
					return err
				}
			}
			if err := decode(raw); err != nil {
				t.Fatal(err)
			}
			for i := 0; i < len(raw); i++ {
				if err := decode(raw[:i]); err == nil {
					t.Fatalf("truncation %d accepted", i)
				}
			}
			if err := decode(append(append([]byte(nil), raw...), 0)); err == nil {
				t.Fatal("trailing bytes accepted")
			}
			changed := append([]byte(nil), raw...)
			changed[8] = 'X'
			if err := decode(changed); err == nil {
				t.Fatal("unknown tag accepted")
			}
		})
	}
	decoded, err := RehydrateCatalogSupersessionState(state, bindings)
	if err != nil {
		t.Fatal(err)
	}
	encoded, _ := decoded.PersistenceEncoding()
	if !bytes.Equal(state, encoded) {
		t.Fatal("state changed on restore")
	}
	for _, kind := range []string{"result-tuple", "result-revision", "result-support", "graph-revision", "reviewer", "cycle", "noncanonical-support", "protection"} {
		t.Run(kind, func(t *testing.T) {
			bad := next
			bad.edges = next.History()
			switch kind {
			case "result-tuple":
				bad.edges[0].Result.New = bad.edges[0].Result.Old
			case "result-revision":
				bad.edges[0].Result.AggregateRevision.value++
			case "result-support":
				bad.edges[0].Result.Support = nil
			case "graph-revision":
				bad.edges[0].Command.ExpectedSupersession.value++
			case "reviewer":
				bad.edges[0].Reviewer = IssuerPrincipal{}
			case "cycle":
				bad.edges = append(bad.edges, bad.edges[0])
			case "noncanonical-support":
				bad.edges[0].Command.Support = append(bad.edges[0].Command.Support, bad.edges[0].Command.Support[0])
			case "protection":
				bad.edges[0].Result.ProtectedCustom = true
				copy := cloneSupersessionEntry(bad.edges[0])
				copy.Result.ProtectedCustom = false
				bad.edges = append(bad.edges, copy)
			}
			if err := bad.validate(); err == nil {
				t.Fatal("corrupt history accepted")
			}
		})
	}
}

func TestSupersessionGoldenVectors(t *testing.T) {
	for _, variant := range []int{0, 1, 2} {
		t.Run(fmt.Sprint(variant), func(t *testing.T) {
			s, cap, c, ctx := supersessionFixture(t)
			if variant == 1 {
				c.Evidence = append(c.Evidence, supersessionEvidence(t, c, 11, 12))
				c.Support = append(c.Support, c.Evidence[1].ID())
			}
			if variant == 2 {
				c.Old.order, _ = NewVersionOrderEvidence("legacy", 7)
				s, _ = NewCatalogSupersessionState(c.Content, []ContentVersion{c.Old, c.New})
				ctx.OldReview = supersessionReview(t, c.Old, false)
			}
			next, r := supersessionApply(t, s, cap, c, ctx)
			command, _ := c.CanonicalEncoding(cap)
			result, _ := r.CanonicalEncoding()
			state, _ := next.PersistenceEncoding()
			expected := supersessionGolden[variant]
			for i, actual := range [][]byte{command, result, state} {
				want, err := hex.DecodeString(expected[i])
				if err != nil {
					t.Fatal(err)
				}
				if !bytes.Equal(actual, want) {
					t.Fatalf("vector %d differs: got %x", i, actual)
				}
			}
			if variant == 1 {
				c.Evidence[0], c.Evidence[1] = c.Evidence[1], c.Evidence[0]
				c.Support[0], c.Support[1] = c.Support[1], c.Support[0]
				permuted, _ := c.CanonicalEncoding(cap)
				if !bytes.Equal(permuted, command) {
					t.Fatal("permutation changed command")
				}
			}
		})
	}
	var e catalogEncoder
	e.data = make([]byte, 0)
	e.number(0)
	e.text("A")
	if hex.EncodeToString(e.data) != "0000000000000000000000000000000141" {
		t.Fatal("primitive framing")
	}
}

func FuzzCatalogSupersessionState(f *testing.F) {
	raw, err := hex.DecodeString(supersessionGolden[0][2])
	if err != nil {
		f.Fatal(err)
	}
	f.Add(raw)
	f.Add([]byte{})
	f.Fuzz(func(t *testing.T, raw []byte) {
		if len(raw) > int(RetainedBytes.Maximum())+1 {
			return
		}
		state, err := RehydrateCatalogSupersessionState(raw, CatalogPersistenceBindings{AllowUnbound: true})
		if err != nil {
			return
		}
		encoded, err := state.PersistenceEncoding()
		if err != nil || !bytes.Equal(raw, encoded) {
			t.Fatal("noncanonical state accepted")
		}
	})
}

// Reconstruct a valid structural history directly, as a repository reader
// would, to exercise total graph/observation bounds independently of Apply's
// owner-validated review snapshots. Evidence shares one exact retained record.
func supersessionBoundedHistory(t *testing.T, edgeCount, perEdge int) CatalogSupersessionState {
	t.Helper()
	_, cap, command, _ := supersessionFixture(t)
	versions := make([]ContentVersion, edgeCount+1)
	for i := range versions {
		id, err := identity.ParseContentVersionID(fmt.Sprintf("ver_%026x", i+1))
		if err != nil {
			t.Fatal(err)
		}
		versions[i], _ = NewContentVersion(id, command.Content, command.New.fingerprint, UnknownVersionOrderEvidence())
	}
	s, err := NewCatalogSupersessionState(command.Content, versions)
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < edgeCount; i++ {
		c := command
		c.ID, _ = RehydrateCatalogCommandID(fmt.Sprintf("%032x", 4096+i))
		c.Old, c.New = versions[i], versions[i+1]
		c.ExpectedAggregate, c.ExpectedSupersession = CatalogRevision{uint64(i + 3)}, CatalogRevision{uint64(i + 1)}
		c.Evidence, c.Support = nil, nil
		for j := 0; j < perEdge; j++ {
			e := supersessionEvidence(t, c, 9, 10)
			e.input.ID, err = evidence.ParseID(fmt.Sprintf("obs_%026x", i*perEdge+j+1))
			if err != nil {
				t.Fatal(err)
			}
			c.Evidence, c.Support = append(c.Evidence, e), append(c.Support, e.ID())
		}
		r := CatalogSupersessionResult{Command: c.ID, Content: c.Content, Old: c.Old, New: c.New, AggregateRevision: CatalogRevision{uint64(i + 4)}, SupersessionRevision: CatalogRevision{uint64(i + 2)}, OldReviewRevision: c.ExpectedOldReview, NewReviewRevision: c.ExpectedNewReview, OrderRevision: CatalogRevision{3}, Support: append([]evidence.ID(nil), c.Support...)}
		s.edges = append(s.edges, CatalogSupersessionEntry{Command: c, Reviewer: cap.Reviewer(), Result: r})
	}
	return s
}

func TestSupersessionRetainedBounds(t *testing.T) {
	max := supersessionBoundedHistory(t, 1023, 1)
	if _, err := max.RetainedEncodingSize(); err != nil {
		t.Fatal("exact edge bound", err)
	}
	tooMany := max
	tooMany.edges = append(max.History(), max.edges[0])
	if err := tooMany.validate(); err == nil {
		t.Fatal("1024 edges accepted")
	}
	exact := supersessionBoundedHistory(t, 64, 64)
	if _, err := exact.RetainedEncodingSize(); err != nil {
		t.Fatal("4096 observations", err)
	}
	over := supersessionBoundedHistory(t, 65, 64)
	var limit LimitError
	if _, err := over.RetainedEncodingSize(); !errors.As(err, &limit) || limit.Resource != RetainedObservations {
		t.Fatal("4160 observations accepted", err)
	}
}

func TestSupersessionCanonicalMutationAndOrder(t *testing.T) {
	_, cap, c, _ := supersessionFixture(t)
	original, err := c.CanonicalEncoding(cap)
	if err != nil {
		t.Fatal(err)
	}
	for _, field := range []string{"reason", "reviewer", "aggregate", "supersession", "old-review", "new-review", "source", "tuple"} {
		t.Run(field, func(t *testing.T) {
			bad, grant := cloneSupersessionCommand(c), cap
			switch field {
			case "reason":
				bad.Reason = "different"
			case "reviewer":
				grant.review.reviewer.value[0] = 1
			case "aggregate":
				bad.ExpectedAggregate.value++
			case "supersession":
				bad.ExpectedSupersession.value++
			case "old-review":
				bad.ExpectedOldReview.value++
			case "new-review":
				bad.ExpectedNewReview.value++
			case "tuple":
				bad.Old.order, _ = NewVersionOrderEvidence("legacy", math.MaxUint64)
			case "source":
				_, grant, _, _ = supersessionFixture(t)
				grant.Source().binding.revision.value[0] = 1
				bad.Source = grant.Source()
				bad.Evidence[0].input.Coordinate.artifact.source = bad.Source
			}
			encoded, err := bad.CanonicalEncoding(grant)
			if err != nil || bytes.Equal(original, encoded) {
				t.Fatal("canonical identity ignored mutation", err)
			}
			decoded, reviewer, err := RehydrateCatalogSupersessionCommand(encoded, CatalogPersistenceBindings{Sources: []SourceRegistration{grant.Source()}, Reviewers: []IssuerPrincipal{grant.Reviewer()}})
			if err != nil || reviewer != grant.Reviewer() || decoded.Old != bad.Old {
				t.Fatal("roundtrip changed tuple", err)
			}
		})
	}
	bad := c
	bad.Old.order = VersionOrderEvidence{namespace: "garbage"}
	if _, err := bad.CanonicalEncoding(cap); !errors.Is(err, ErrInvalidCatalog) {
		t.Fatal("inactive order garbage accepted", err)
	}
}

func TestSupersessionStagingBounds(t *testing.T) {
	for _, tc := range []struct {
		name  string
		count int
		bytes uint64
		limit bool
	}{
		{"batches-exact", 256, 2, false}, {"batches-over", 257, 2, true},
		{"bytes-exact", 64, 1 << 20, false}, {"bytes-over", 65, 1 << 20, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			s := supersessionBoundedHistory(t, tc.count, 1)
			for i := range s.edges {
				coord := &s.edges[i].Command.Evidence[0].input.Coordinate
				coord.artifact.facts.ID.value = [16]byte{}
				binary.BigEndian.PutUint64(coord.artifact.facts.ID.value[8:], uint64(10000+i))
				coord.artifact.facts.ByteLength = tc.bytes
			}
			_, err := s.RetainedEncodingSize()
			if tc.limit {
				var limit LimitError
				if !errors.As(err, &limit) {
					t.Fatal("one-over admitted", err)
				}
			} else if err != nil {
				t.Fatal("exact bound rejected", err)
			}
		})
	}
}

func TestSupersessionSuccessorSupport(t *testing.T) {
	s, cap, c, ctx := supersessionFixture(t)
	source, ingest := testRegistration(t, CoreOperator, FingerprintClaimKey, OwnershipClaimKey)
	review, _ := NewReviewCapability(cap.Reviewer(), source)
	subject, _ := VersionSubject(c.Content, c.New.id)
	state, _ := NewCatalogReviewState(subject, false)
	want, _ := FingerprintClaim(c.New.fingerprint)
	other, _ := FingerprintClaim(c.Old.fingerprint)
	a := registrationObservation(t, source, subject, want, 14, 15)
	b := registrationObservation(t, source, subject, other, 16, 17)
	_ = ingest
	for _, operation := range []CatalogReviewCommand{
		{ID: CatalogCommandID{value: registrationOpaque(20)}, Kind: RecordObservations, Subject: subject, Source: source, Expected: CatalogRevision{1}, Observations: []CatalogObservation{a, b}, Reason: "stage"},
		{ID: CatalogCommandID{value: registrationOpaque(21)}, Kind: AcceptSupport, Subject: subject, Source: source, Expected: CatalogRevision{2}, Key: FingerprintClaimKey, Support: []evidence.ID{a.ID(), b.ID()}, Reason: "accept"},
	} {
		var err error
		state, _, err = state.Apply(review, operation)
		if err != nil {
			t.Fatal(err)
		}
	}
	if state.Field(FingerprintClaimKey).Status != CatalogFactConflict {
		t.Fatal("fixture lacks real contradictory acceptance")
	}
	ctx.NewReview = state
	c.ExpectedNewReview = state.Revision()
	supersessionReject(t, s, cap, c, ctx, ErrCatalogUnsupported)
}
